def generate_next_token(x_new, kv_cache=None):
    q_new, k_new, v_new = project_qkv(x_new)
    if kv_cache is not None:
        # Append newest key and value along the sequence dimension
        k_full = torch.cat([kv_cache['k'], k_new], dim=1)
        v_full = torch.cat([kv_cache['v'], v_new], dim=1)
    else:
        k_full, v_full = k_new, v_new

    new_kv_cache = {'k': k_full, 'v': v_full}
    output = attention(q_new, k_full, v_full)
