def reward_loss(r_chosen, r_rejected):
    # r_chosen is scalar score for preferred response
    # r_rejected is scalar score for dispreferred response
    return -torch.log(torch.sigmoid(r_chosen - r_rejected)).mean()

# Reward penalty against policy drift
def compute_objective(reward, logp_policy, logp_ref, kl_coef=0.1):
    kl = logp_policy - logp_ref
    return reward - kl_coef * kl

