def verify_tokens(p_draft_logits, p_target_logits, draft_tokens):
    accepted = []
    for i, tok in enumerate(draft_tokens):
        p_t = p_target_logits[i, tok]
        p_d = p_draft_logits[i, tok]
        # Accept with probability ratio
        if torch.rand(1).item() < min(1.0, (p_t / p_d).item()):
            accepted.append(tok)
        else:
            break # Stop at first rejected token and sample correction
    return accepted

