# Reciprocal Rank Fusion (RRF) algorithm
def reciprocal_rank_fusion(dense_ranks, sparse_ranks, k=60):
    combined_scores = {}
    all_docs = set(dense_ranks.keys()).union(set(sparse_ranks.keys()))

    for doc in all_docs:
        score = 0
        if doc in dense_ranks:
            score += 1.0 / (k + dense_ranks[doc])
        if doc in sparse_ranks:
            score += 1.0 / (k + sparse_ranks[doc])
        combined_scores[doc] = score

    # Sort descending
    return sorted(combined_scores.items(), key=lambda x: x[1], reverse=True)

