# Ternary weight quantization to {-1, 0, 1}
def quantize_ternary(w, eps=1e-5):
    scale = w.abs().mean()
    w_scaled = w / (scale + eps)
    # Round to nearest integer and clamp to -1, 0, 1
    return torch.clamp(torch.round(w_scaled), -1, 1), scale

